// BLONDA AKAI — the gen~ operators used by the BLONDA Max for Live devices, with gen's semantics, for code
// generated by tools/gen2cpp.py. Everything is double precision like gen~.
#pragma once
#include <cmath>
#include <cstdint>
#include <cstring>
#include <vector>

namespace akai::gen {

constexpr double kPi = 3.14159265358979323846, kTwoPi = 6.28318530717958647692, kHalfPi = 1.57079632679489661923,
                 kE = 2.71828182845904523536;

// white noise in [-1, 1)
struct Noise {
    uint32_t s = 0x5EEDu;
    void seed(uint32_t v) { s = v ? v : 0x5EEDu; }
    double next() { s ^= s << 13; s ^= s >> 17; s ^= s << 5; return (double)(int32_t)s * (1.0 / 2147483648.0); }
};

// Data / Buffer: frames x channels, interleaved. Allocated once (constructor or host load), never in tick().
struct Data {
    int frames = 0, chans = 1;
    std::vector<double> v;
    Data() = default;
    Data(int n, int ch) : frames(n), chans(ch < 1 ? 1 : ch), v((size_t)n * (size_t)(ch < 1 ? 1 : ch), 0.0) {}
    void resize(int n, int ch) { frames = n; chans = ch < 1 ? 1 : ch; v.assign((size_t)n * (size_t)chans, 0.0); }
    void clear() { std::fill(v.begin(), v.end(), 0.0); }
};
using Buffer = Data;

// peek/poke: index in samples, truncated; out of range reads 0 and writes nothing (gen's default "ignore")
inline double peek(const Data& d, double index, double channel = 0) {
    const long i = (long)std::floor(index), c = (long)std::floor(channel);
    if (i < 0 || i >= d.frames || c < 0 || c >= d.chans) return 0.0;
    return d.v[(size_t)i * (size_t)d.chans + (size_t)c];
}
inline void poke(Data& d, double value, double index, double channel = 0) {
    const long i = (long)std::floor(index), c = (long)std::floor(channel);
    if (i < 0 || i >= d.frames || c < 0 || c >= d.chans) return;
    d.v[(size_t)i * (size_t)d.chans + (size_t)c] = value;
}
inline double dim(const Data& d) { return d.frames; }
inline double channels(const Data& d) { return d.chans; }

inline double wrap(double x, double lo, double hi) {
    const double r = hi - lo;
    if (r == 0.0) return lo;
    double y = std::fmod(x - lo, r);
    if (y < 0.0) y += r;
    return lo + y;
}
inline double clamp(double x, double lo, double hi) { return x < lo ? lo : (x > hi ? hi : x); }
inline double min(double a, double b) { return a < b ? a : b; }
inline double max(double a, double b) { return a > b ? a : b; }
inline double abs(double x) { return std::fabs(x); }
inline double floor(double x) { return std::floor(x); }
inline double ceil(double x) { return std::ceil(x); }
inline double round(double x) { return std::round(x); }
inline double trunc(double x) { return std::trunc(x); }
inline double fract(double x) { return x - std::floor(x); }
inline double sign(double x) { return x > 0 ? 1.0 : (x < 0 ? -1.0 : 0.0); }
inline double pow(double a, double b) { return std::pow(a, b); }
inline double exp(double x) { return std::exp(x); }
inline double exp2(double x) { return std::exp2(x); }
inline double log(double x) { return x > 0 ? std::log(x) : -1e300; }
inline double log2(double x) { return x > 0 ? std::log2(x) : -1e300; }
inline double log10(double x) { return x > 0 ? std::log10(x) : -1e300; }
inline double sqrt(double x) { return x > 0 ? std::sqrt(x) : 0.0; }
inline double sin(double x) { return std::sin(x); }
inline double cos(double x) { return std::cos(x); }
inline double tan(double x) { return std::tan(x); }
inline double tanh(double x) { return std::tanh(x); }
inline double sinh(double x) { return std::sinh(x); }
inline double cosh(double x) { return std::cosh(x); }
inline double atan(double x) { return std::atan(x); }
inline double atan2(double y, double x) { return std::atan2(y, x); }
inline double asin(double x) { return std::asin(clamp(x, -1, 1)); }
inline double acos(double x) { return std::acos(clamp(x, -1, 1)); }
inline double mix(double a, double b, double t) { return a + (b - a) * t; }
inline double mtof(double n) { return 440.0 * std::exp2((n - 69.0) / 12.0); }
inline double ftom(double f) { return f > 0 ? 69.0 + 12.0 * std::log2(f / 440.0) : -1e300; }
inline double dbtoa(double db) { return std::pow(10.0, db / 20.0); }
inline double atodb(double a) { return a > 0 ? 20.0 * std::log10(a) : -1e300; }
inline double fixdenorm(double x) { return std::fabs(x) < 1e-30 ? 0.0 : x; }
inline double fixnan(double x) { return x == x ? x : 0.0; }
inline double dim2(double a, double b) { return a > b ? a - b : 0.0; }

} // namespace akai::gen
